// Contact Form JavaScript
(function() {
    'use strict';

    // Defer PostHog tracking to avoid blocking
    function trackPageView() {
        setTimeout(function() {
            window.trackEvent('page_view', {
                page: 'contact',
                page_type: 'contact_form'
            });
        }, 1000);
    }

    // Validation functions
    const commonTypos = {
        'gamil.com': 'gmail.com', 'gmial.com': 'gmail.com', 'gnail.com': 'gmail.com',
        'gmail.con': 'gmail.com', 'gmail.co': 'gmail.com', 'gmai.com': 'gmail.com',
        'hotmial.com': 'hotmail.com', 'hotmil.com': 'hotmail.com', 'hotmail.con': 'hotmail.com',
        'yaho.com': 'yahoo.com', 'yahho.com': 'yahoo.com', 'yahoo.con': 'yahoo.com',
        'outllok.com': 'outlook.com', 'outlok.com': 'outlook.com', 'outlook.con': 'outlook.com'
    };

    function validateEmail(email) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(email)) {
            return { valid: false, message: 'Please enter a valid email address' };
        }

        const domain = email.toLowerCase().split('@')[1];
        if (commonTypos[domain]) {
            return {
                valid: false,
                message: `Did you mean ${email.replace(domain, commonTypos[domain])}?`,
                suggestion: email.replace(domain, commonTypos[domain])
            };
        }

        return { valid: true };
    }

    function validateUSPhone(value) {
        const digits = value.replace(/\D/g, '');
        if (!digits) return { valid: true };
        if (digits.length === 10) {
            return { valid: true, formatted: `+1${digits}` };
        }
        return { valid: false, message: 'Please enter a valid 10-digit US phone number' };
    }

    function validateName(name) {
        if (name.trim().length < 2) {
            return { valid: false, message: 'Name must be at least 2 characters long' };
        }
        return { valid: true };
    }

    function validateMessage(message) {
        if (message.trim().length < 10) {
            return { valid: false, message: 'Message must be at least 10 characters long' };
        }
        return { valid: true };
    }

    function showValidation(field, isValid, message = '') {
        if (isValid) {
            field.classList.remove('is-invalid');
            field.classList.add('is-valid');
        } else {
            field.classList.remove('is-valid');
            field.classList.add('is-invalid');
        }
    }

    function showMessage(message, type) {
        // Remove existing messages
        const existingMessages = document.querySelectorAll('.alert-message');
        existingMessages.forEach(msg => {
            msg.style.opacity = '0';
            msg.style.transform = 'translateY(-10px)';
            setTimeout(() => msg.remove(), 300);
        });

        // Create new message element
        const messageDiv = document.createElement('div');
        messageDiv.className = `alert-message alert alert-${type === 'success' ? 'success' : 'danger'}`;
        messageDiv.setAttribute('role', 'alert');
        messageDiv.setAttribute('aria-live', 'polite');
        
        // Add icon
        const icon = type === 'success' ? '✓' : '✕';
        messageDiv.innerHTML = `<strong>${icon}</strong> ${message}`;
        
        // Initial hidden state for animation
        messageDiv.style.opacity = '0';
        messageDiv.style.transform = 'translateY(-10px)';
        messageDiv.style.transition = 'all 0.3s ease';

        // Insert at the top of form container for better visibility
        const form = document.getElementById('contactForm');
        const formContainer = form ? form.closest('.contact-form-container') : null;
        
        if (formContainer) {
            formContainer.insertBefore(messageDiv, formContainer.firstChild);
            
            // Animate in and scroll to message
            setTimeout(() => {
                messageDiv.style.opacity = '1';
                messageDiv.style.transform = 'translateY(0)';
                // Smooth scroll to message
                messageDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            }, 10);

            // Auto-remove after 8 seconds (longer for better visibility)
            setTimeout(() => {
                messageDiv.style.opacity = '0';
                messageDiv.style.transform = 'translateY(-10px)';
                setTimeout(() => {
                    if (messageDiv.parentNode) {
                        messageDiv.remove();
                    }
                }, 300);
            }, 8000);
        } else if (form) {
            // Fallback: insert after form
            form.parentNode.insertBefore(messageDiv, form.nextSibling);
            setTimeout(() => {
                messageDiv.style.opacity = '1';
                messageDiv.style.transform = 'translateY(0)';
                messageDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            }, 10);
            setTimeout(() => {
                messageDiv.style.opacity = '0';
                messageDiv.style.transform = 'translateY(-10px)';
                setTimeout(() => {
                    if (messageDiv.parentNode) {
                        messageDiv.remove();
                    }
                }, 300);
            }, 8000);
        }
    }

    // Setup phone input formatting
    function setupPhoneInput(phoneInput) {
        if (!phoneInput) return;

        // Phone input - prevent letters and format as typed
        phoneInput.addEventListener('keypress', function(e) {
            // Only allow digits (0-9)
            if (e.key < '0' || e.key > '9') {
                e.preventDefault();
                return false;
            }
        });

        phoneInput.addEventListener('input', function() {
            // Remove any non-digit characters
            const digits = this.value.replace(/\D/g, '');

            // Limit to 10 digits
            const limitedDigits = digits.slice(0, 10);

            // Format as (###) ###-####
            let formatted = '';
            if (limitedDigits.length >= 6) {
                formatted = `(${limitedDigits.slice(0, 3)}) ${limitedDigits.slice(3, 6)}-${limitedDigits.slice(6, 10)}`;
            } else if (limitedDigits.length >= 3) {
                formatted = `(${limitedDigits.slice(0, 3)}) ${limitedDigits.slice(3)}`;
            } else if (limitedDigits.length > 0) {
                formatted = `(${limitedDigits}`;
            }

            this.value = formatted;
        });

        // Allow navigation and editing keys
        phoneInput.addEventListener('keydown', function(e) {
            // Allow: backspace, delete, tab, escape, enter, home, end, left, right, up, down
            if ([8, 9, 27, 13, 46, 35, 36, 37, 38, 39, 40].indexOf(e.keyCode) !== -1 ||
                // Allow: Ctrl+A, Ctrl+C, Ctrl+V, Ctrl+X
                (e.keyCode === 65 && e.ctrlKey === true) ||
                (e.keyCode === 67 && e.ctrlKey === true) ||
                (e.keyCode === 86 && e.ctrlKey === true) ||
                (e.keyCode === 88 && e.ctrlKey === true)) {
                return;
            }
        });
    }

    // Setup validation on blur
    function setupValidation() {
        const emailInput = document.getElementById('email');
        const phoneInput = document.getElementById('phone');
        const nameInput = document.getElementById('name');
        const messageTextarea = document.getElementById('message');

        if (!emailInput || !phoneInput || !nameInput || !messageTextarea) {
            return;
        }

        // Setup phone input formatting
        setupPhoneInput(phoneInput);

        const validateOnBlur = (field, validator) => {
            field.addEventListener('blur', function() {
                const result = validator(this.value);
                showValidation(this, result.valid, result.message);

                if (!result.valid && result.suggestion && field === emailInput) {
                    if (confirm(result.message + '\n\nWould you like to use the suggested email?')) {
                        this.value = result.suggestion;
                        showValidation(this, true);
                    }
                }
            });
        };

        // Apply validation with delay to avoid blocking
        setTimeout(() => {
            validateOnBlur(emailInput, validateEmail);
            validateOnBlur(phoneInput, validateUSPhone);
            validateOnBlur(nameInput, validateName);
            validateOnBlur(messageTextarea, validateMessage);
        }, 100);
    }

    // Prefill form from URL parameters or cookies
    function prefillForm() {
        const contactForm = document.getElementById('contactForm');
        if (!contactForm) return;

        const subjectSelect = contactForm.querySelector('#subject');
        const nameInput = contactForm.querySelector('#name');
        const emailInput = contactForm.querySelector('#email');
        const messageTextarea = contactForm.querySelector('#message');

        // Get URL parameters
        const urlParams = new URLSearchParams(window.location.search);
        const subjectParam = urlParams.get('subject');
        const nameParam = urlParams.get('name');
        const emailParam = urlParams.get('email');
        const messageParam = urlParams.get('message');

        // Get cookie values
        function getCookie(name) {
            const value = `; ${document.cookie}`;
            const parts = value.split(`; ${name}=`);
            if (parts.length === 2) return decodeURIComponent(parts.pop().split(';').shift());
            return null;
        }

        const subjectCookie = getCookie('contact_subject');
        const nameCookie = getCookie('contact_name');
        const emailCookie = getCookie('contact_email');

        // Prefill subject (URL param takes precedence over cookie)
        if (subjectParam && subjectSelect) {
            // Decode the parameter (URLSearchParams should handle this, but be safe)
            const decodedParam = decodeURIComponent(subjectParam);
            
            // Try to find exact match first
            const exactMatch = Array.from(subjectSelect.options).find(opt => 
                opt.value === decodedParam || opt.value === subjectParam
            );
            if (exactMatch) {
                subjectSelect.value = exactMatch.value;
            } else {
                // Try partial match (case-insensitive)
                const partialMatch = Array.from(subjectSelect.options).find(opt => {
                    const optLower = opt.value.toLowerCase();
                    const paramLower = decodedParam.toLowerCase();
                    return optLower.includes(paramLower) || paramLower.includes(optLower);
                });
                if (partialMatch) {
                    subjectSelect.value = partialMatch.value;
                } else {
                    // Log for debugging if no match found
                    console.warn('No dropdown match found for subject:', decodedParam);
                }
            }
            // Save to cookie for future visits
            if (subjectSelect.value) {
                document.cookie = `contact_subject=${encodeURIComponent(subjectSelect.value)}; path=/; max-age=86400`; // 24 hours
            }
        } else if (subjectCookie && subjectSelect) {
            const decodedCookie = decodeURIComponent(subjectCookie);
            const cookieMatch = Array.from(subjectSelect.options).find(opt => 
                opt.value === decodedCookie || opt.value === subjectCookie
            );
            if (cookieMatch) {
                subjectSelect.value = cookieMatch.value;
            }
        }

        // Prefill name (URL param takes precedence over cookie)
        if (nameParam && nameInput) {
            nameInput.value = decodeURIComponent(nameParam);
            document.cookie = `contact_name=${encodeURIComponent(nameParam)}; path=/; max-age=86400`;
        } else if (nameCookie && nameInput && !nameInput.value) {
            nameInput.value = nameCookie;
        }

        // Prefill email (URL param takes precedence over cookie)
        if (emailParam && emailInput) {
            emailInput.value = decodeURIComponent(emailParam);
            document.cookie = `contact_email=${encodeURIComponent(emailParam)}; path=/; max-age=86400`;
        } else if (emailCookie && emailInput && !emailInput.value) {
            emailInput.value = emailCookie;
        }

        // Prefill message (only from URL param, not cookie)
        if (messageParam && messageTextarea) {
            messageTextarea.value = decodeURIComponent(messageParam);
        }

        // Clear URL parameters after prefilling (optional - keeps clean URL)
        if (subjectParam || nameParam || emailParam || messageParam) {
            const cleanUrl = window.location.pathname;
            window.history.replaceState({}, document.title, cleanUrl);
        }
    }

    // Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', function() {
        trackPageView();

    const contactForm = document.getElementById('contactForm');
    
    if (contactForm) {
            // Prefill form from URL params or cookies
            prefillForm();

            // Setup form validation
            setTimeout(() => {
                setupValidation();
            }, 500);

            // Handle form submission
        contactForm.addEventListener('submit', function(e) {
            e.preventDefault();
            
            // Convert phone to E.164 format before submission
            const phoneInput = contactForm.querySelector('#phone');
            if (phoneInput && phoneInput.value) {
                const digits = phoneInput.value.replace(/\D/g, '');
                if (digits.length === 10) {
                    phoneInput.value = `+1${digits}`;
                }
            }
            
            const formData = new FormData(contactForm);
            const submitBtn = contactForm.querySelector('button[type="submit"]');
            const originalText = submitBtn.textContent;
            
            // Show loading state
            submitBtn.textContent = 'Sending...';
            submitBtn.disabled = true;
            
            fetch('/api/contact', {
                method: 'POST',
                body: formData
            })
                .then(response => {
                    if (!response.ok) {
                        return response.json().then(data => {
                            throw new Error(data.error || `Server error: ${response.status}`);
                        });
                    }
                    return response.json();
                })
            .then(data => {
                if (data.success) {
                            // Track form submission with all form data
                            const formDataObj = {};
                            for (let [key, value] of formData.entries()) {
                                formDataObj[key] = value;
                            }
                            
                            window.trackEvent('form_submitted', {
                                form_name: 'contact_form',
                                success: true,
                                form_data: formDataObj,
                                timestamp: new Date().toISOString()
                            });
                    
                    // Show success message
                        showMessage('Message sent successfully! I\'ll get back to you soon.', 'success');
                    contactForm.reset();
                        
                        // Reset validation states
                        const fields = contactForm.querySelectorAll('.is-valid, .is-invalid');
                        fields.forEach(field => {
                            field.classList.remove('is-valid', 'is-invalid');
                        });
                } else {
                            // Track failed form submission
                            window.trackEvent('form_submitted', {
                                form_name: 'contact_form',
                                success: false,
                                error_message: data.error || 'Failed to send message',
                                timestamp: new Date().toISOString()
                            });
                    
                        // Show error message with details
                        let errorMsg = data.error || 'Failed to send message';
                        if (data.errors && typeof data.errors === 'object') {
                            const errorList = Object.values(data.errors).join('. ');
                            if (errorList) {
                                errorMsg = errorList;
                            }
                        }
                        showMessage(errorMsg, 'error');
                }
            })
            .catch(error => {
                console.error('Error:', error);
                    const errorMsg = error.message || 'An error occurred. Please check your connection and try again.';
                    showMessage(errorMsg, 'error');
            })
            .finally(() => {
                // Reset button state
                submitBtn.textContent = originalText;
                submitBtn.disabled = false;
            });
        });
    }

        // PostHog event tracking for form interactions
        const contactForm = document.getElementById('contactForm');
        
        if (contactForm) {
            // Track form view
            window.trackEvent('contact_form_viewed', {
                form_name: 'contact_form'
            });
            
            // Track form field interactions
            const formFields = contactForm.querySelectorAll('input, textarea, select');
            formFields.forEach(field => {
                field.addEventListener('focus', function() {
                    window.trackEvent('contact_form_field_focused', {
                        form_name: 'contact_form',
                        field_name: this.name || this.id,
                        field_type: this.type || 'textarea'
                    });
                });
            });
        }
    });
})();
